/**
 * Distribui o gabarito entre A e E (a posição da correta segue a ordem 0,1,2,3,4,...),
 * girando as alternativas. Evita que "chutar sempre a mesma letra" funcione.
 */
const ORDEM_RFB = [
  "Língua Portuguesa", "Língua Inglesa", "Raciocínio Lógico", "Economia", "Administração", "Direito Administrativo", "Auditoria",
  "Contabilidade", "Fluência de Dados", "Direito Constitucional", "Direito Previdenciário", "Direito Tributário",
  "Legislação Aduaneira", "Comércio Internacional",
];
export const QUESTOES_RFB: QuestaoME[] = [...QUESTOES_RFB_BASE]
  .sort((a, b) => ORDEM_RFB.indexOf(a.materia) - ORDEM_RFB.indexOf(b.materia))
  .map((q, i) => {
  const alvo = ((i * 3) % 5) as QuestaoME["correta"];
  const desloc = (alvo - q.correta + 5) % 5;
  const alternativas = q.alternativas.map((_, idx) => q.alternativas[(idx - desloc + 5) % 5]) as QuestaoME["alternativas"];
  return { ...q, alternativas, correta: alvo };
});

